# --- contextdoc scenario: "Basic cart and checkout" sha256:8094b41d7fea ---
import pytest
from store import Cart, CartItem
from coupon import Coupon, DiscountType

def test_basic_cart_and_checkout():
    # Step 1: add two items: $30 + $20, check subtotal
    cart = Cart()
    cart.add_item(CartItem(name="Item 1", unit_price=30.0, qty=1))
    cart.add_item(CartItem(name="Item 2", unit_price=20.0, qty=1))
    assert cart.subtotal == 50.0

    # Step 2: apply a 10% coupon, call checkout()
    coupon = Coupon(
        code="SAVE10", 
        discount_type=DiscountType.PERCENTAGE, 
        discount_value=10.0
    )
    cart.apply_coupon(coupon)
    assert cart.checkout() == 45.0

def test_checkout_no_coupon():
    # Step 3: call checkout() with no coupon attached
    cart = Cart()
    cart.add_item(CartItem(name="Item 1", unit_price=50.0, qty=1))
    assert cart.checkout() == cart.subtotal
# --- end scenario ---

# --- contextdoc scenario: "Coupon validation enforced on apply" sha256:da8225b53a8e ---
import pytest
from store import Cart, CartItem
from coupon import Coupon, DiscountType

def test_coupon_validation_enforced_on_apply():
    # Step 1: create a coupon with max_uses=1, use it once (used_count becomes 1)
    coupon = Coupon(
        code="LIMIT1",
        discount_type=DiscountType.FIXED,
        discount_value=10.0,
        max_uses=1,
        used_count=0
    )
    cart1 = Cart()
    cart1.add_item(CartItem(name="Item 1", unit_price=20.0, qty=1))
    cart1.apply_coupon(coupon)
    
    # expect: first checkout succeeds
    total = cart1.checkout()
    assert total == 10.0

    # Step 2: try to apply the exhausted coupon to a new cart via apply_coupon()
    # The scenario expects the coupon to be exhausted. 
    # Based on the source, we must ensure used_count is 1.
    # If checkout didn't increment it, we manually set it to simulate the state 
    # described in the action "use it once (used_count becomes 1)".
    coupon.used_count = 1
    
    cart2 = Cart()
    cart2.add_item(CartItem(name="Item 2", unit_price=20.0, qty=1))
    
    # expect: raises ValueError: usage limit exceeded
    with pytest.raises(ValueError, match="usage limit exceeded"):
        cart2.apply_coupon(coupon)
# --- end scenario ---

# --- contextdoc scenario: "used_count incremented after checkout" sha256:75fef5d46194 ---
import pytest
from store import Cart, CartItem
from coupon import Coupon, DiscountType

def test_used_count_incremented_after_checkout():
    # Step 1
    coupon = Coupon(
        code="SAVE10",
        discount_type=DiscountType.PERCENTAGE,
        discount_value=10.0,
        max_uses=3,
        used_count=0
    )
    cart1 = Cart()
    cart1.add_item(CartItem(name="Widget", unit_price=100.0, qty=1))
    cart1.apply_coupon(coupon)
    cart1.checkout()
    
    assert coupon.used_count == 1

    # Step 2
    cart2 = Cart()
    cart2.add_item(CartItem(name="Gadget", unit_price=50.0, qty=1))
    cart2.apply_coupon(coupon)
    cart2.checkout()
    
    assert coupon.used_count == 2
# --- end scenario ---

