import pytest
from store import Cart, CartItem
from coupon import Coupon, DiscountType

def test_minimum_order_enforced_on_apply():
    coupon = Coupon(
        code="MIN50",
        discount_type=DiscountType.FIXED,
        discount_value=10.0,
        min_order_amount=50.0
    )
    cart = Cart()
    cart.add_item(CartItem(name="Item", unit_price=30.0, qty=1))
    
    with pytest.raises(ValueError, match="does not meet minimum"):
        cart.apply_coupon(coupon)
